alter table public.booking_settings add column if not exists allow_extended_rental boolean not null default false, add column if not exists additional_hour_price_cents integer not null default 0 check(additional_hour_price_cents>=0), add column if not exists overnight_available boolean not null default false, add column if not exists overnight_price_cents integer not null default 0 check(overnight_price_cents>=0), add column if not exists allow_same_day_multiple_bookings boolean not null default false;
alter table public.inventory_items add column if not exists allow_extended_rental_override boolean, add column if not exists additional_hour_price_cents_override integer check(additional_hour_price_cents_override>=0), add column if not exists overnight_available_override boolean, add column if not exists overnight_price_cents_override integer check(overnight_price_cents_override>=0);
alter table public.booking_items add column if not exists standard_rental_hours_snapshot integer, add column if not exists additional_hours integer not null default 0, add column if not exists overnight_selected boolean not null default false, add column if not exists duration_adjustment_cents integer not null default 0;
